def is_publishable_path(dotfolder: str, rel_path: str, *, size: int) -> bool:
    if size > MAX_CONTENT_SCAN_BYTES:
        return False
    parts = rel_path.replace("\\", "/").split("/")
    name = parts[-1]
    if len(parts) > 1:
        return False
    if name == "stub.txt":
